`timescale 1ns / 1ps
// Repro for uart_tx: a start pulse while a frame is in flight must be ignored,
// so the in-flight byte must be transmitted unchanged (8N1, LSB first).
module uart_tx_rca_repro;
    localparam integer CPB = 4;

    reg        clk = 1'b0;
    reg        rst = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data = 8'h00;
    wire       tx;
    wire       busy;

    integer passed = 0;
    integer failed = 0;
    integer i;
    reg     done = 1'b0;
    reg [8*64-1:0] nonce;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task check(input exp, input [8*24-1:0] what);
        begin
            if (tx === exp) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL %0s: tx=%b expected %b at %0t", what, tx, exp, $time);
            end
        end
    endtask

    task verdict;
        begin
            if (!done) begin
                done = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
                $finish;
            end
        end
    endtask

    // Send one frame; optionally pulse start with another byte during data bit 2.
    task send(input [7:0] b, input inject, input [7:0] other);
        begin
            @(negedge clk); start = 1'b1; data = b;
            @(negedge clk); start = 1'b0; data = 8'h00;  // start bit began at that posedge
            @(negedge clk);                              // mid start bit
            check(1'b0, "start bit");
            for (i = 0; i < 8; i = i + 1) begin
                if (inject && i == 2) begin
                    @(negedge clk); start = 1'b1; data = other;
                    @(negedge clk); start = 1'b0; data = 8'h00;
                    repeat (2) @(negedge clk);
                end else
                    repeat (CPB) @(negedge clk);
                check(b[i], "data bit");
            end
            repeat (CPB) @(negedge clk);
            check(1'b1, "stop bit");
            repeat (2 * CPB) @(negedge clk);
            if (busy === 1'b0 && tx === 1'b1) passed = passed + 1;
            else begin
                failed = failed + 1;
                $display("FAIL idle after frame: busy=%b tx=%b at %0t", busy, tx, $time);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);
        send(8'h5A, 1'b0, 8'h00);
        send(8'hA5, 1'b1, 8'h3C);
        verdict;
    end

    initial begin
        #100000;
        $display("FAIL watchdog timeout");
        failed = failed + 1;
        verdict;
    end
endmodule
=== END FILE ===

{"uncertainty": 0.15, "outcome": "rtl_bug", "artifacts": [{"kind": "root_cause_analysis", "title": "Root cause: uart_tx reloads the hold register on a start pulse while a frame is in flight", "summary": "Conclusion: rtl_bug in [artifact:prj-d4a591eb4b.design-under-investigation.a1]. The header of uart_tx_reload_while_busy.v specifies 8N1 framing and says that 'a start pulse while a frame is in flight is ignored'. Defect: the always block runs 'if (start) hold <= data;' before the case statement, outside the IDLE branch, so a start pulse in any state overwrites hold. Causality: in DATA the next bit is driven from hold[bit_idx + 1], so every data bit sent after a mid-frame start comes from the new byte. In the attached repro, a start carrying 8'h3C during data bit 2 of 8'hA5 makes bits 3, 4 and 7 differ from the specified byte, and the tx check on those bits fails. Incorrectness: the header states that a mid-frame start must be ignored, and the load already present inside the IDLE branch implies that loading belongs only there. Removing the unconditional load and keeping the IDLE load should fix this failure and any other mid-frame start, for every byte value. This is consistent with the triage evidence [evidence:prj-d4a591eb4b.triage.e1] (top hypothesis: Likely RTL bug, only 30% confidence, so it was treated as one candidate rather than accepted) and [evidence:prj-d4a591eb4b.triage.e2] (triage testbench reached $finish with 1 of 4 checks failed). Competing hypotheses, ranked, with the reason each was rejected and what would refute this conclusion: (1) rtl_bug, accepted. It is refuted if the repro still fails on RTL without the top-level 'if (start) hold <= data'. (2) testbench_bug, rejected. The expected values in the repro come from the specified framing and the input byte, not from DUT output. Each sample is taken one clock into its bit window, and the first, uninjected frame is fully checked as a control. This is refuted if the control frame fails or the repro fails on the clean RTL. (3) infrastructure, rejected. Per [evidence:prj-d4a591eb4b.triage.e2] the build ran, reached $finish and produced a counted verdict, so this is a functional mismatch rather than a tool or build fault. This is refuted if a clean rebuild with no other change passes. (4) spec_ambiguity, rejected. The clause the check relies on states the busy-start behaviour explicitly. This is refuted if a governing specification outside the RTL header allows reload while busy; none was provided to this seat. Requirement traced: [requirement:req-d10c4df532]."}], "files": [{"path": "uart_tx_rca_repro.v", "kind": "testbench", "title": "Self-checking repro: start pulse during a frame must not alter the transmitted byte", "summary": "Self-checking testbench for [artifact:prj-d4a591eb4b.design-under-investigation.a1] that uses only the module ports. Frame 1 (8'h5A) is a clean control. Frame 2 (8'hA5) receives a start pulse with 8'h3C during data bit 2. Expected tx values come from the specified 8N1, LSB-first framing and the rule that a start pulse while busy is ignored. The testbench counts its passed and failed checks and prints one NIRMAAN-SIM verdict line with the plusarg nonce just before $finish. It is expected to fail on the RTL under investigation (data bits 3, 4 and 7 of frame 2) and to pass on RTL that ignores start while busy. It serves [requirement:req-d10c4df532].", "entry": "uart_tx_rca_repro"}], "tool_runs": [], "claims": ["By reading the RTL, the repro is expected to report 3 failed checks (data bits 3, 4 and 7 of the injected frame) on the RTL under investigation. This has not been run by this seat.", "The repro is expected to pass on RTL where hold loads only in IDLE. This is not verified.", "The only specification text available to this seat is the header comment of the RTL file; no separate specification document was read."], "escalation": null, "notes": "Resubmission of attempt 1. Attempt 1 was refused because it listed run-0001 and run-0002 in tool_runs, and those runs are not recorded. tool_runs is now empty, and this analysis cites the triage evidence tokens instead. The testbench content is unchanged. The reproduction gate (simulator.run, expect=fail) and the independent review are left to the platform and to a reviewer; this seat claims neither."}

